import {LawIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'
import type {AlertEvent, ExceptionAddedEventBody} from '../../../types/alerts'
import {TimelineEventWithActor, parseEventBody} from './shared'
import styles from './shared.module.css'

interface ExceptionAddedEventProps {
  event: AlertEvent
  repoLicensePolicyPath?: string
  repoName?: string
}

export function ExceptionAddedEvent({event, repoLicensePolicyPath, repoName}: ExceptionAddedEventProps) {
  const exceptionInfo = parseEventBody<ExceptionAddedEventBody>(event.eventBody)

  return (
    <TimelineEventWithActor
      event={event}
      icon={<LawIcon size={16} />}
      actionText={
        exceptionInfo?.package_manager && exceptionInfo?.package_name ? (
          <>
            added {exceptionInfo.package_manager}/{exceptionInfo.package_name}
            {repoLicensePolicyPath && (
              <>
                {' to '}
                <Link href={repoLicensePolicyPath} className={styles.defaultColorLink} data-testid="policy-link">
                  {/*
                    Distributed policy is hardcoded, but we need to pass it in from
                    alert when we end up implementing multiple policies. In the
                    meantime, use generic language.
                  */}
                  license policy
                </Link>
              </>
            )}
            {repoName && <span data-testid="repo-name"> for {repoName}</span>}
          </>
        ) : (
          'created exception'
        )
      }
      data-testid="timeline-event-exception-added"
    />
  )
}
