import {ArrowLeftIcon} from '@primer/octicons-react'
import {IconButton, Stack, Text} from '@primer/react'

type WorkflowDialogPageTitleProps = {
  title: string
  subtitle?: string
  showBackButton: boolean
  onBack?: () => void
  backButtonAriaLabel: string
  backButtonTestId?: string
}

export function WorkflowDialogPageTitle({
  title,
  subtitle,
  showBackButton,
  onBack,
  backButtonAriaLabel,
  backButtonTestId,
}: WorkflowDialogPageTitleProps) {
  return (
    <Stack direction="horizontal" gap="none">
      {showBackButton && (
        <IconButton
          data-testid={backButtonTestId}
          aria-label={backButtonAriaLabel}
          className="mr-1"
          icon={ArrowLeftIcon}
          variant="invisible"
          onClick={onBack}
        />
      )}
      <Stack direction="vertical" className="pt-1">
        {title}
        {subtitle && (
          <Text size="small" weight="normal" className="fgColor-muted lh-default pt-1">
            {subtitle}
          </Text>
        )}
      </Stack>
    </Stack>
  )
}
