import type React from 'react'
import {encodePart} from '@github-ui/paths'
import {AlertPageHeader, AlertPageHeaderLink} from '@github-ui/platform-patterns/AlertPageHeader'
import {type Alert, AlertStatus} from '../types/alerts'

export interface LicenseComplianceAlertHeaderProps {
  alert: Alert
  owner?: string
  repo?: string
  buttonGroup?: React.ReactNode
}

export const LicenseComplianceAlertHeader = ({alert, owner, repo, buttonGroup}: LicenseComplianceAlertHeaderProps) => (
  <AlertPageHeader
    title={`Non-compliant license expression found on ${alert.packageName}`}
    alertNumber={alert.number}
    status={alert.status === AlertStatus.Closed ? 'fixed' : 'open'}
    subtitle={
      <>
        On <span className="text-bold">{alert.packageName}</span>
        {` (${alert.packageEcosystem}) `}
        {owner && repo && (
          <AlertPageHeaderLink
            href={`/${owner}/${repo}/blob/${encodePart(alert.branchName || '-')}/${alert.manifestName}`}
          >
            {alert.manifestName}
          </AlertPageHeaderLink>
        )}
      </>
    }
    timestamp={new Date(alert.createdAtIso)}
    buttonGroup={buttonGroup}
  />
)
