import {useState} from 'react'
import {Dialog} from '@primer/react'
import type {Alert} from '../../types/alerts'
import {PolicyLevel} from '../../types/policies'
import {
  BaseSharedDismissalForm,
  validateComment,
  validateReasonSelected,
} from '@github-ui/shared-dismissal/base-shared-dismissal-form'

import {PolicyUpdateForm} from '../DialogForms/PolicyUpdateForm'
import {useUserPermissions} from '../../context/UserPermissionsContext'
import {useReviewerOnlyWorkflowMutations} from './use-reviewer-only-workflow-mutations'
import {usePolicyUpdateFormState} from '../DialogForms/use-policy-update-form-state'
import {WorkflowDialogPageTitle} from '../WorkflowDialogPageTitle'
import {submitPolicyUpdate} from '../DialogForms/submit-policy-update'

interface ReviewerOnlyWorkflowDialogProps {
  alert: Alert
  onClose: () => void
  onError: (error: string) => void
  owner: string
  repo: string
  dismissalOptions: Array<{value: string; label: string; description: string}>
}

export function ReviewerOnlyWorkflowDialog({
  alert,
  onClose,
  onError,
  owner,
  repo,
  dismissalOptions,
}: ReviewerOnlyWorkflowDialogProps) {
  // Page index starting at 0 for easier dialogCopyByPage array lookup
  const [currentPage, setCurrentPage] = useState(0)

  const commentRequired = true

  // states for DismissalForm form
  const [comment, setComment] = useState('')
  const [commentError, setCommentError] = useState('')
  const [reasonChoice, setReasonChoice] = useState('')
  const [reasonChoiceError, setReasonChoiceError] = useState<string | null>(null)

  const policyUpdateFormState = usePolicyUpdateFormState(alert.packageName)

  // setup mutations for both pages of the dialog
  const mutations = useReviewerOnlyWorkflowMutations({
    owner,
    repo,
    alertNumber: alert.number.toString(),
    onError,
    onSettled: onClose,
  })

  // bail if user doesn't have permission to review dismissal requests for the alert
  const {canManageRepositoryPolicy, canManageEnterprisePolicy} = useUserPermissions()
  if (!canManageRepositoryPolicy && !canManageEnterprisePolicy) {
    return null
  }

  // handle field value changes and validations for DismissalForm
  const handleCommentChange = (value: string) => {
    setComment(value)

    if (validateComment({dismissalComment: value, commentRequired})) {
      setCommentError('')
    }
  }

  const handleReasonChange = (value: string) => {
    setReasonChoice(value)

    if (validateReasonSelected({reason: value})) {
      setReasonChoiceError('')
    }
  }

  const validatePage0Inputs = () => {
    const nextCommentError = validateComment({dismissalComment: comment, commentRequired})
      ? ''
      : 'Comment cannot be empty'
    setCommentError(nextCommentError)

    const nextReasonChoiceError = validateReasonSelected({reason: reasonChoice}) ? '' : 'Dismissal reason is required'
    setReasonChoiceError(nextReasonChoiceError)

    return Boolean(nextCommentError || nextReasonChoiceError)
  }

  // handle form submissions
  const handleSubmitPage0 = () => {
    const hasError = validatePage0Inputs()
    if (hasError) return

    setCurrentPage(1)
  }

  const handleSubmitPage1 = () => {
    const hasError = policyUpdateFormState.validateInputs()
    if (hasError) return

    submitPolicyUpdate({
      comment,
      closureReason: reasonChoice,
      amendment: policyUpdateFormState.amendment,
      scope: policyUpdateFormState.scope as PolicyLevel,
      wildcardPattern: policyUpdateFormState.wildcardPattern,
      onCreatePolicyException: args => mutations.createExceptionMutation.mutate(args),
      onAddLicensesForAlert: args => mutations.addLicensesForAlertMutation.mutate(args),
    })
  }

  const handleSubmit = () => {
    if (currentPage === 0) {
      handleSubmitPage0()
      return
    }

    handleSubmitPage1()
  }

  const dialogCopyByPage = [
    {
      title: 'Close alert',
      buttonText: 'Update policy',
    },
    {
      title: (
        <WorkflowDialogPageTitle
          title="Create policy update"
          subtitle="Complete alert closure by updating the policy"
          showBackButton
          onBack={() => setCurrentPage(0)}
          backButtonAriaLabel="Back to close alert"
          backButtonTestId="back-button"
        />
      ),
      buttonText: 'Create update',
    },
  ]

  return (
    <Dialog
      onClose={onClose}
      title={dialogCopyByPage[currentPage]?.title}
      footerButtons={[
        {
          buttonType: 'default',
          content: 'Cancel',
          onClick: onClose,
          disabled: mutations.isLoading,
        },
        {
          buttonType: 'primary',
          content: dialogCopyByPage[currentPage]?.buttonText,
          onClick: handleSubmit,
          loading: mutations.isLoading,
        },
      ]}
    >
      {currentPage === 0 && (
        <BaseSharedDismissalForm
          error={null}
          disabled={mutations.isLoading}
          commentRequired={commentRequired}
          dismissalOptions={dismissalOptions}
          reasonSelected={reasonChoice}
          onReasonChange={handleReasonChange}
          reasonValidationError={reasonChoiceError}
          dismissalComment={comment}
          onDismissalCommentChange={handleCommentChange}
          commentValidationError={commentError}
          radioGroupName="reviewer-only-dismissal-reason"
        />
      )}
      {currentPage === 1 && (
        <PolicyUpdateForm
          alert={alert}
          owner={owner}
          repo={repo}
          canManageEnterprisePolicy={canManageEnterprisePolicy}
          amendment={policyUpdateFormState.amendment}
          onAmendmentChange={policyUpdateFormState.setAmendment}
          scope={policyUpdateFormState.scope}
          onScopeChange={policyUpdateFormState.setScope}
          wildcardPattern={policyUpdateFormState.wildcardPattern}
          onWildcardChange={policyUpdateFormState.onWildcardChange}
          wildcardValidationError={policyUpdateFormState.wildcardValidationError}
        />
      )}
    </Dialog>
  )
}
