import {ArrowUpRightIcon, LawIcon, RepoIcon} from '@primer/octicons-react'
import {ActionList} from '@primer/react'
import {AlertMetadata} from '@github-ui/platform-patterns/AlertPageSidebar'

export interface LicenseComplianceAlertSidePaneProps {
  repoLicensePolicyPath?: string
  externalPackageManagerUrl?: string
  packageRepositoryUrl?: string
  packageName: string
  packageEcosystem: string
}

/**
 * Validates that a URL uses http or https protocol.
 * Returns true for valid http/https URLs, false otherwise.
 */
function isValidHttpUrl(url: string): boolean {
  try {
    const parsed = new URL(url, window.location.origin)
    return parsed.protocol === 'http:' || parsed.protocol === 'https:'
  } catch {
    return false
  }
}

/**
 * Extracts "owner/repo" from a GitHub repository URL.
 * Example: "https://github.com/lodash/lodash" -> "lodash/lodash"
 */
function getRepoDisplayName(url: string): string {
  const match = url.match(/github\.com\/([^/]+\/[^/]+)/)
  return match?.[1] ?? url
}

export const LicenseComplianceAlertSidePane: React.FC<LicenseComplianceAlertSidePaneProps> = ({
  repoLicensePolicyPath,
  externalPackageManagerUrl,
  packageRepositoryUrl,
  packageName,
  packageEcosystem,
}) => {
  const validRepoUrl = packageRepositoryUrl && isValidHttpUrl(packageRepositoryUrl) ? packageRepositoryUrl : undefined
  const validPkgManagerUrl =
    externalPackageManagerUrl && isValidHttpUrl(externalPackageManagerUrl) ? externalPackageManagerUrl : undefined
  const hasPackageDetails = validRepoUrl || validPkgManagerUrl

  return (
    <>
      {repoLicensePolicyPath && (
        <AlertMetadata title="License policy" headingTag="h2">
          <ActionList variant="full">
            <ActionList.LinkItem href={repoLicensePolicyPath}>
              <ActionList.LeadingVisual>
                <LawIcon />
              </ActionList.LeadingVisual>
              {/* NOTE: This used to say "Distributed policy," and that would technically be correct,
              but that's the only policy we support now so it's clearer to just keep in general. */}
              View policy
            </ActionList.LinkItem>
          </ActionList>
        </AlertMetadata>
      )}

      {hasPackageDetails && (
        <AlertMetadata title="Package details" headingTag="h2" testId="package-details-section">
          <ActionList variant="full">
            {validRepoUrl && (
              <ActionList.LinkItem
                href={validRepoUrl}
                target="_blank"
                rel="noopener noreferrer"
                data-testid="package-repository-link"
              >
                <ActionList.LeadingVisual>
                  <RepoIcon />
                </ActionList.LeadingVisual>
                {getRepoDisplayName(validRepoUrl)}
              </ActionList.LinkItem>
            )}
            {validPkgManagerUrl && (
              <ActionList.LinkItem
                href={validPkgManagerUrl}
                target="_blank"
                rel="noopener noreferrer"
                data-testid="package-manager-link"
              >
                <ActionList.LeadingVisual>
                  <ArrowUpRightIcon />
                </ActionList.LeadingVisual>
                {`${packageName} on ${packageEcosystem}`}
              </ActionList.LinkItem>
            )}
          </ActionList>
        </AlertMetadata>
      )}
    </>
  )
}
