import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {
  requestAlertDismissal,
  requestAlertDismissalWithComment,
  createPackageException,
  denyAlertDismissal,
  addLicensesForAlert,
} from '../services/alerts'
import {licenseComplianceAlertRoute} from '../routes/license-compliance-alert-route'
import type {PolicyLevel, PackageAction} from '../types/policies'

export type UseRequestDismissalMutationProps = {
  owner: string
  repo: string
  number: string
  onError: (message: string) => void
}

export type UseRequestDismissalWithCommentMutationProps = {
  owner: string
  repo: string
  number: string
  onError: (message: string) => void
  onSettled: () => void
}

export type UseCreatePackageExceptionMutationProps = {
  owner: string
  repo: string
  number: string
  onError: (message: string) => void
  onSettled: () => void
}

export type UseAddLicensesForAlertMutationProps = {
  owner: string
  repo: string
  number: string
  onError: (message: string) => void
  onSettled: () => void
}

export type UseDenyRequestMutationProps = {
  owner: string
  repo: string
  number: string
  onError: (message: string) => void
  onSettled: () => void
}

export function useRequestDismissalMutation({owner, repo, number, onError}: UseRequestDismissalMutationProps) {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')

  return useMutation({
    mutationFn: () => requestAlertDismissal(owner, repo, number),
    onSuccess: () => {
      onError('')
      queryClient.invalidateQueries({queryKey})
    },
    onError: (e: Error) => {
      onError(`Failed to close alert: ${e.message}`)
    },
  })
}

export function useRequestDismissalWithCommentMutation({
  owner,
  repo,
  number,
  onError,
  onSettled,
}: UseRequestDismissalWithCommentMutationProps) {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')

  return useMutation({
    mutationFn: ({reason, comment}: {reason: string; comment: string}) =>
      requestAlertDismissalWithComment(owner, repo, number, reason, comment),
    onSuccess: () => {
      onError('')
      queryClient.invalidateQueries({queryKey})
    },
    onError: (e: Error) => {
      onError(`Failed to close alert: ${e.message}`)
    },
    onSettled: () => onSettled(),
  })
}

export function useCreatePackageExceptionMutation({
  owner,
  repo,
  number,
  onError,
  onSettled,
}: UseCreatePackageExceptionMutationProps) {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')

  return useMutation({
    mutationFn: ({
      comment,
      policyLevel,
      packageAction,
      pattern,
      closureReason,
    }: {
      comment: string
      policyLevel: PolicyLevel
      packageAction: PackageAction
      pattern: string
      closureReason?: string
    }) => createPackageException(owner, repo, number, comment, policyLevel, packageAction, pattern, closureReason),
    onSuccess: () => {
      onError('')
      queryClient.invalidateQueries({queryKey})
    },
    onError: (e: Error) => {
      onError(`Failed to create package exception: ${e.message}`)
    },
    onSettled: () => onSettled(),
  })
}

export function useAddLicensesForAlertMutation({
  owner,
  repo,
  number,
  onError,
  onSettled,
}: UseAddLicensesForAlertMutationProps) {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')

  return useMutation({
    mutationFn: ({
      comment,
      policyLevel,
      closureReason,
    }: {
      comment: string
      policyLevel: PolicyLevel
      closureReason?: string
    }) => addLicensesForAlert(owner, repo, number, comment, policyLevel, closureReason),
    onSuccess: () => {
      onError('')
      queryClient.invalidateQueries({queryKey})
    },
    onError: (e: Error) => {
      onError(`Failed to add licenses for alert: ${e.message}`)
    },
    onSettled: () => onSettled(),
  })
}

export function useDenyRequestMutation({owner, repo, number, onError, onSettled}: UseDenyRequestMutationProps) {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')

  return useMutation({
    mutationFn: (comment: string) => denyAlertDismissal(owner, repo, number, comment),
    onSuccess: () => {
      onError('')
      queryClient.invalidateQueries({queryKey})
    },
    onError: (e: Error) => {
      onError(`Failed to deny alert: ${e.message}`)
    },
    onSettled: () => onSettled(),
  })
}
