import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useParams} from '@github-ui/react-router'
import {assertDataPresent} from '@github-ui/assert-data-present'
import {licenseComplianceAlertRoute} from './license-compliance-alert-route'
import {AlertStatus} from '../types/alerts'
import {PageLayout, Banner, Button} from '@primer/react'
import {LicenseComplianceAlertDescription} from '../components/LicenseComplianceAlertDescription'
import {LicenseComplianceAlertHeader} from '../components/LicenseComplianceAlertHeader'
import {LicenseComplianceAlertSidePane} from '../components/LicenseComplianceAlertSidePane'
import {RequestWorkflowDialog} from '../components/RequestWorkflowDialog/RequestWorkflowDialog'
import {ReviewWorkflowDialog} from '../components/ReviewWorkflowDialog/ReviewWorkflowDialog'
import {ReviewerOnlyWorkflowDialog} from '../components/ReviewerOnlyWorkflowDialog/ReviewerOnlyWorkflowDialog'
import {AlertTimeline} from '../components/timeline/AlertTimeline'
import {useMemo, useState} from 'react'
import {UserPermissionsProvider, useUserPermissions} from '../context/UserPermissionsContext'
import type {LicenseComplianceAlertResponse} from './license-compliance-alert-route'

interface ResolvedReviewPermissions {
  canManageRepositoryPolicy: boolean
  canManageEnterprisePolicy: boolean
}

/**
 * TODO: Remove once the dependency_graph_eoslm_switch feature flag is removed.
 * Reconciles the legacy and new license-policy permission shapes into the booleans the UI consumes.
 */
export function resolveReviewPermissions(
  permissions: LicenseComplianceAlertResponse['permissions'],
): ResolvedReviewPermissions {
  if (permissions.useNewLicensePolicyPermissions) {
    return {
      canManageRepositoryPolicy: Boolean(permissions.canManageRepositoryLicensePolicy),
      canManageEnterprisePolicy: Boolean(permissions.canManageEnterpriseLicensePolicy),
    }
  }

  // Legacy fallback: the single review permission implied the ability to manage both scopes.
  const legacy = Boolean(permissions.canReviewLicenseComplianceAlertDismissalRequest)
  return {
    canManageRepositoryPolicy: legacy,
    canManageEnterprisePolicy: legacy,
  }
}

export function LicenseComplianceAlert() {
  const {
    data: {alert, repoLicensePolicyPath, permissions, dismissalOptions},
  } = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')
  const {canRequestLicenseComplianceAlertDismissal} = permissions
  const {canManageRepositoryPolicy, canManageEnterprisePolicy} = resolveReviewPermissions(permissions)

  const {owner, repo, number} = useParams<{
    owner?: string
    repo?: string
    number?: string
  }>()

  assertDataPresent(owner)
  assertDataPresent(repo)
  assertDataPresent(number)

  const [bannerMessage, setBannerMessage] = useState('')

  return (
    <UserPermissionsProvider
      canManageRepositoryPolicy={canManageRepositoryPolicy}
      canManageEnterprisePolicy={canManageEnterprisePolicy}
      canRequestLicenseComplianceAlertDismissal={Boolean(canRequestLicenseComplianceAlertDismissal)}
    >
      <LicenseComplianceAlertContent
        alert={alert}
        repoLicensePolicyPath={repoLicensePolicyPath}
        owner={owner}
        repo={repo}
        bannerMessage={bannerMessage}
        setBannerMessage={setBannerMessage}
        dismissalOptions={dismissalOptions ?? []}
      />
    </UserPermissionsProvider>
  )
}

type LicenseComplianceAlertContentProps = {
  alert: LicenseComplianceAlertResponse['alert']
  repoLicensePolicyPath?: string
  owner: string
  repo: string
  bannerMessage: string
  setBannerMessage: (message: string) => void
  dismissalOptions: Array<{value: string; label: string; description: string}>
}

function LicenseComplianceAlertContent({
  alert,
  repoLicensePolicyPath,
  owner,
  repo,
  bannerMessage,
  setBannerMessage,
  dismissalOptions,
}: LicenseComplianceAlertContentProps) {
  const {canManageRepositoryPolicy, canManageEnterprisePolicy, canRequestLicenseComplianceAlertDismissal} =
    useUserPermissions()
  const canManageAtLeastOnePolicy = canManageRepositoryPolicy || canManageEnterprisePolicy

  // State for workflow modals
  const [isRequestWorkflowModalOpen, setIsRequestWorkflowModalOpen] = useState(false)
  const [isReviewWorkflowModalOpen, setIsReviewWorkflowModalOpen] = useState(false)
  const [isReviewerOnlyWorkflowModalOpen, setIsReviewerOnlyWorkflowModalOpen] = useState(false)

  // Determine which buttons to show on Alert page
  const showRequestWorkflowCloseButton = useMemo(() => {
    if (dismissalOptions.length === 0) return false
    if (alert.status !== AlertStatus.Open && alert.status !== AlertStatus.ReviewDenied) return false
    if (canRequestLicenseComplianceAlertDismissal && canManageAtLeastOnePolicy) return false
    return canRequestLicenseComplianceAlertDismissal
  }, [alert.status, canRequestLicenseComplianceAlertDismissal, canManageAtLeastOnePolicy, dismissalOptions])

  const showReviewWorkflowTimelineButton = useMemo(() => {
    return alert.status === AlertStatus.ReviewRequested && canManageAtLeastOnePolicy
  }, [alert.status, canManageAtLeastOnePolicy])

  const showReviewerOnlyWorkflowCloseButton = useMemo(() => {
    if (dismissalOptions.length === 0) return false
    if (alert.status !== AlertStatus.Open && alert.status !== AlertStatus.ReviewDenied) return false
    return canManageAtLeastOnePolicy
  }, [alert.status, canManageAtLeastOnePolicy, dismissalOptions])

  return (
    <PageLayout>
      <PageLayout.Header>
        {bannerMessage && (
          <Banner
            className="tmp-mb-3"
            variant="warning"
            title="failed to update alert"
            hideTitle
            description={bannerMessage}
          />
        )}
        <LicenseComplianceAlertHeader
          alert={alert}
          owner={owner}
          repo={repo}
          buttonGroup={
            <>
              {showRequestWorkflowCloseButton && (
                <Button
                  data-testid="request-workflow-modal-header-close-button"
                  onClick={() => setIsRequestWorkflowModalOpen(true)}
                >
                  Close alert
                </Button>
              )}
              {showReviewerOnlyWorkflowCloseButton && (
                <Button
                  data-testid="reviewer-only-workflow-modal-header-close-button"
                  onClick={() => setIsReviewerOnlyWorkflowModalOpen(true)}
                >
                  Close alert
                </Button>
              )}
            </>
          }
        />
      </PageLayout.Header>
      <PageLayout.Content as="div">
        <LicenseComplianceAlertDescription
          license={alert.license}
          packageEcosystem={alert.packageEcosystem}
          packageName={alert.packageName}
          packageVersion={alert.packageVersion}
        />
        {isRequestWorkflowModalOpen && (
          <RequestWorkflowDialog
            alert={alert}
            onClose={() => {
              setIsRequestWorkflowModalOpen(false)
            }}
            onError={setBannerMessage}
            owner={owner}
            repo={repo}
            dismissalOptions={dismissalOptions}
          />
        )}
        {isReviewWorkflowModalOpen && (
          <ReviewWorkflowDialog
            alert={alert}
            onClose={() => setIsReviewWorkflowModalOpen(false)}
            onError={setBannerMessage}
            owner={owner}
            repo={repo}
          />
        )}
        {isReviewerOnlyWorkflowModalOpen && (
          <ReviewerOnlyWorkflowDialog
            alert={alert}
            onClose={() => {
              setIsReviewerOnlyWorkflowModalOpen(false)
            }}
            onError={setBannerMessage}
            owner={owner}
            repo={repo}
            dismissalOptions={dismissalOptions}
          />
        )}
        {alert.events && alert.events.length > 0 && (
          <AlertTimeline
            events={alert.events}
            alertResolution={alert.resolution}
            closureReason={alert.closureReason}
            onReviewRequest={showReviewWorkflowTimelineButton ? () => setIsReviewWorkflowModalOpen(true) : undefined}
            repoLicensePolicyPath={repoLicensePolicyPath}
            repoName={repo}
          />
        )}
      </PageLayout.Content>
      <PageLayout.Pane>
        <LicenseComplianceAlertSidePane
          repoLicensePolicyPath={repoLicensePolicyPath}
          externalPackageManagerUrl={alert.externalPackageManagerUrl}
          packageRepositoryUrl={alert.packageRepositoryUrl}
          packageName={alert.packageName}
          packageEcosystem={alert.packageEcosystem}
        />
      </PageLayout.Pane>
    </PageLayout>
  )
}
