import {useState} from 'react'

import {PolicyLevel} from '../../types/policies'
import {AMENDMENT_PACKAGE, AMENDMENT_PACKAGE_WILDCARD} from './constants'
import {getWildcardPatternValidationError} from './wildcard-pattern-validation'

export function usePolicyUpdateFormState(packageName: string) {
  const [amendment, setAmendment] = useState(AMENDMENT_PACKAGE)
  const [scope, setScope] = useState<string>(PolicyLevel.Repository)
  const [wildcardPattern, setWildcardPattern] = useState(`${packageName}*`)
  const [wildcardValidationError, setWildcardValidationError] = useState('')

  const onWildcardChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setWildcardPattern(event.target.value)
  }

  // Validate inputs and set errors if needed. Returns true if there are errors, false otherwise
  const validateInputs = () => {
    setWildcardValidationError('')

    if (amendment === AMENDMENT_PACKAGE_WILDCARD) {
      const error = getWildcardPatternValidationError(wildcardPattern, packageName)
      if (error) {
        setWildcardValidationError(error)
        return true
      }
    }

    return false
  }

  return {
    amendment,
    setAmendment,
    scope,
    setScope,
    wildcardPattern,
    onWildcardChange,
    wildcardValidationError,
    validateInputs,
  }
}
